<?php
/** Canonical, non-rendering Workshop data service shared by dashboard management. */
if ( ! defined( 'ABSPATH' ) ) { exit; }
class GGM_Workshop_Data_Service {
	private const REPEATERS = array( 'ggm_you_will_discover', 'ggm_why_different_points', 'ggm_workshop_why_workshop_different_points', 'ggm_workshop_journey_days', 'ggm_perfect_for_you', 'ggm_faq' );
	private const TEXT = array( 'Counter_Start_Date', 'workshop_preparatory_date', 'workshop_mode', 'ggm_workshop_header_pill_text', 'workshop_language', 'duration', 'ggm_workshop_featured_video_url', 'ggm_workshop_booking_card_cta_heading', 'ggm_workshop_booking_card_cta_text', 'ggm_workshop_booking_card_testimonial_text', 'ggm_workshop_booking_card_rating_text', 'ggm_workshop_whatsapp_group_url', 'ggm_workshop_form_text_heading', 'ggm_workshop_discover_heading_override', 'ggm_workshop_why_different_heading_override', 'ggm_workshop_perfect_for_heading_override', 'ggm_workshop_faq_heading_override', 'ggm_workshop_discover_bottom_text', 'ggm_workshop_why_different_bottom_text', 'ggm_workshop_perfect_for_bottom_text', 'ggm_workshop_why_workshop_different_heading', 'ggm_workshop_why_workshop_different_intro', 'ggm_workshop_journey_heading' );
	public static function load( $id ) {
		$post=self::workshop($id);if(is_wp_error($post))return $post;$meta=array();foreach(self::TEXT as $key)$meta[$key]=get_post_meta($post->ID,$key,true);foreach(array('workshop_start_date','workshop_end_date','workshop_regular_price','workshop_sale_price','is_free','linked_course_id','ggm_contribution_enabled','ggm_workshop_bottom_image_id') as $key)$meta[$key]=get_post_meta($post->ID,$key,true);$meta['mentor_ids']=self::mentor_ids($post->ID);$meta['ggm_currency_adjustments']=class_exists('GGM_Currency')?GGM_Currency::adjustments_for_item($post->ID):array();foreach(self::REPEATERS as $key)$meta[$key]=self::decode_rows(get_post_meta($post->ID,$key,true));foreach(array('ggm_workshop_booking_card_hero_items','ggm_workshop_journey_footer_items','ggm_contribution_options','ggm_workshop_additional_block_layouts') as $key)$meta[$key]=get_post_meta($post->ID,$key,true)?:array();$meta['ggm_workshop_booking_card_hero_header']=get_post_meta($post->ID,'ggm_workshop_booking_card_hero_header',true);$meta['ggm_workshop_form_text_content']=get_post_meta($post->ID,'ggm_workshop_form_text_content',true);$meta['ggm_workshop_why_workshop_different_image']=get_post_meta($post->ID,'ggm_workshop_why_workshop_different_image',true);$slots=class_exists('GGM_Workshop_Slot')?GGM_Workshop_Slot::get_for_workshop($post->ID,'all'):array();return array('id'=>(int)$post->ID,'title'=>$post->post_title,'content'=>$post->post_content,'status'=>$post->post_status,'featured_image_id'=>(int)get_post_thumbnail_id($post->ID),'meta'=>$meta,'slots'=>array_map(static function($slot){return(array)$slot;},$slots));
	}
	public static function save( $id,array $payload ) {
		$post=self::workshop($id);if(is_wp_error($post))return $post;$payload=self::normalize($payload);$errors=self::validate($post->ID,$payload);if($errors)return new WP_Error('validation_failed',__('Please correct the highlighted fields.','ggm-member-dashboard'),$errors);foreach(self::TEXT as $key)if(array_key_exists($key,$payload))self::save_text($post->ID,$key,$payload[$key]);foreach(array('workshop_start_date','workshop_end_date') as $key)if(array_key_exists($key,$payload))update_post_meta($post->ID,$key,$payload[$key]);foreach(array('workshop_regular_price','workshop_sale_price') as $key)if(array_key_exists($key,$payload))update_post_meta($post->ID,$key,''===$payload[$key]?'':(float)$payload[$key]);if(array_key_exists('linked_course_id',$payload))update_post_meta($post->ID,'linked_course_id',(int)$payload['linked_course_id']);if(array_key_exists('mentor_ids',$payload)){update_post_meta($post->ID,'ggm_mentor_ids',$payload['mentor_ids']);update_post_meta($post->ID,'ggm_mentor_id',$payload['mentor_ids'][0]??0);}if(array_key_exists('featured_image_id',$payload))$payload['featured_image_id']?set_post_thumbnail($post->ID,$payload['featured_image_id']):delete_post_thumbnail($post->ID);if(array_key_exists('ggm_workshop_bottom_image_id',$payload))$payload['ggm_workshop_bottom_image_id']?update_post_meta($post->ID,'ggm_workshop_bottom_image_id',$payload['ggm_workshop_bottom_image_id']):delete_post_meta($post->ID,'ggm_workshop_bottom_image_id');if(array_key_exists('is_free',$payload))update_post_meta($post->ID,'is_free',$payload['is_free']?'1':'');if(array_key_exists('ggm_currency_adjustments',$payload)&&class_exists('GGM_Currency'))GGM_Currency::save_adjustments_for_item($post->ID,$payload['ggm_currency_adjustments']);if(array_key_exists('ggm_contribution_enabled',$payload))update_post_meta($post->ID,'ggm_contribution_enabled',$payload['ggm_contribution_enabled']?'1':'');if(array_key_exists('ggm_contribution_options',$payload))update_post_meta($post->ID,'ggm_contribution_options',$payload['ggm_contribution_options']);foreach(array('ggm_workshop_booking_card_hero_header','ggm_workshop_form_text_content') as $key)if(array_key_exists($key,$payload))update_post_meta($post->ID,$key,wp_kses_post($payload[$key]));if(array_key_exists('ggm_workshop_why_workshop_different_image',$payload))update_post_meta($post->ID,'ggm_workshop_why_workshop_different_image',$payload['ggm_workshop_why_workshop_different_image']);foreach(self::REPEATERS as $key)if(array_key_exists($key,$payload))update_post_meta($post->ID,$key,wp_json_encode($payload[$key]));foreach(array('ggm_workshop_booking_card_hero_items','ggm_workshop_journey_footer_items','ggm_workshop_additional_block_layouts') as $key)if(array_key_exists($key,$payload))update_post_meta($post->ID,$key,$payload[$key]);if(array_key_exists('slots',$payload))self::save_slots($post->ID,$payload['slots']);clean_post_cache($post->ID);return self::load($post->ID);
	}
	public static function normalize(array $input){$out=array();foreach(self::TEXT as $key)if(array_key_exists($key,$input))$out[$key]=self::text($input[$key]);foreach(array('workshop_start_date','workshop_end_date') as $key)if(array_key_exists($key,$input))$out[$key]=sanitize_text_field($input[$key]);foreach(array('workshop_regular_price','workshop_sale_price') as $key)if(array_key_exists($key,$input))$out[$key]=''===trim((string)$input[$key])?'':round((float)$input[$key],2);if(array_key_exists('linked_course_id',$input))$out['linked_course_id']=absint($input['linked_course_id']);if(array_key_exists('mentor_ids',$input))$out['mentor_ids']=array_values(array_unique(array_filter(array_map('absint',(array)$input['mentor_ids']))));foreach(array('featured_image_id','ggm_workshop_bottom_image_id') as $key)if(array_key_exists($key,$input))$out[$key]=absint($input[$key]);if(array_key_exists('is_free',$input))$out['is_free']=!empty($input['is_free']);if(array_key_exists('ggm_contribution_enabled',$input))$out['ggm_contribution_enabled']=!empty($input['ggm_contribution_enabled']);if(array_key_exists('ggm_currency_adjustments',$input)){$out['ggm_currency_adjustments']=array();foreach((array)$input['ggm_currency_adjustments'] as $code=>$amount)$out['ggm_currency_adjustments'][sanitize_key($code)]=max(0,(float)$amount);}if(array_key_exists('ggm_contribution_options',$input))$out['ggm_contribution_options']=self::contributions($input['ggm_contribution_options']);foreach(array('ggm_workshop_booking_card_hero_header','ggm_workshop_form_text_content') as $key)if(array_key_exists($key,$input))$out[$key]=(string)$input[$key];if(array_key_exists('ggm_workshop_why_workshop_different_image',$input))$out['ggm_workshop_why_workshop_different_image']=esc_url_raw($input['ggm_workshop_why_workshop_different_image']);foreach(self::REPEATERS as $key)if(array_key_exists($key,$input))$out[$key]=self::rows($input[$key]);foreach(array('ggm_workshop_booking_card_hero_items','ggm_workshop_journey_footer_items') as $key)if(array_key_exists($key,$input))$out[$key]=self::rows($input[$key]);if(array_key_exists('ggm_workshop_additional_block_layouts',$input)){$out['ggm_workshop_additional_block_layouts']=array();foreach(array('discover','why_different','perfect_for')as$section){$row=(array)($input['ggm_workshop_additional_block_layouts'][$section]??array());$out['ggm_workshop_additional_block_layouts'][$section]=array('columns'=>min(8,absint($row['columns']??0)),'rows'=>min(10,absint($row['rows']??0)));}}if(array_key_exists('slots',$input))$out['slots']=array_values((array)$input['slots']);return$out;}
	public static function validate($workshop_id,array $payload){$errors=array();$start=$payload['workshop_start_date']??get_post_meta($workshop_id,'workshop_start_date',true);$end=$payload['workshop_end_date']??get_post_meta($workshop_id,'workshop_end_date',true);if(($start&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))||($end&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))||($start&&$end&&$end<$start))$errors['workshop_dates']=__('End date must not be before start date.','ggm-member-dashboard');$regular=$payload['workshop_regular_price']??get_post_meta($workshop_id,'workshop_regular_price',true);$sale=$payload['workshop_sale_price']??get_post_meta($workshop_id,'workshop_sale_price',true);if(''!==$sale&&(float)$sale>(float)$regular)$errors['workshop_sale_price']=__('Sale price cannot exceed regular price.','ggm-member-dashboard');if(isset($payload['linked_course_id'])&&$payload['linked_course_id']&&'course'!==get_post_type($payload['linked_course_id']))$errors['linked_course_id']=__('Choose a valid Course.','ggm-member-dashboard');foreach((array)($payload['mentor_ids']??array())as$id)if('ggm_mentor'!==get_post_type($id))$errors['mentor_ids']=__('Choose valid Mentors.','ggm-member-dashboard');foreach(array('featured_image_id','ggm_workshop_bottom_image_id')as$key)if(!empty($payload[$key])&&(!wp_attachment_is_image($payload[$key])||!current_user_can('edit_post',$payload[$key])))$errors[$key]=__('Choose an image from the Media Library.','ggm-member-dashboard');foreach(array('ggm_workshop_featured_video_url','ggm_workshop_whatsapp_group_url')as$key)if(isset($payload[$key])&&$payload[$key]&&!filter_var($payload[$key],FILTER_VALIDATE_URL))$errors[$key]=__('Enter a valid URL.','ggm-member-dashboard');if(isset($payload['slots'])&&class_exists('GGM_Workshop_Slot'))foreach($payload['slots']as$slot){$a=sanitize_text_field($slot['start_time']??$slot['start']??'');$b=sanitize_text_field($slot['end_time']??$slot['end']??'');$id=absint($slot['id']??0);if($id&&(!$existing=GGM_Workshop_Slot::get($id)||(int)$existing->workshop_id!==(int)$workshop_id))$errors['slots']=__('Invalid Workshop slot.','ggm-member-dashboard');if(($a||$b)&&!GGM_Workshop_Slot::validate_range($a,$b))$errors['slots']=__('Each time slot must end after it starts.','ggm-member-dashboard');}return$errors;}
	private static function workshop($id){$post=get_post(absint($id));return$post&&in_array($post->post_type,array('workshop','ggm_workshop'),true)?$post:new WP_Error('invalid_workshop',__('Workshop not found.','ggm-member-dashboard'));}
	private static function mentor_ids($id){$ids=get_post_meta($id,'ggm_mentor_ids',true);if(!is_array($ids))$ids=array();if(!$ids&&($legacy=absint(get_post_meta($id,'ggm_mentor_id',true))))$ids=array($legacy);return array_values(array_filter(array_map('absint',$ids)));}
	private static function text($v){return is_scalar($v)?sanitize_textarea_field((string)$v):'';}
	private static function save_text($id,$key,$v){if(in_array($key,array('ggm_workshop_featured_video_url','ggm_workshop_whatsapp_group_url'),true))$v=esc_url_raw($v);if('workshop_language'===$key)$v=in_array(sanitize_key($v),array('english','hindi'),true)?sanitize_key($v):'english';update_post_meta($id,$key,$v);}
	private static function decode_rows($v){if(is_string($v))$v=json_decode($v,true);return is_array($v)?$v:array();}
	private static function rows($rows){$out=array();foreach((array)$rows as$row){if(!is_array($row))continue;$clean=array();foreach($row as$key=>$v){$key=sanitize_key($key);$clean[$key]=in_array($key,array('description','answer','content'),true)?wp_kses_post($v):(false!==strpos($key,'image')||'icon'===$key?esc_url_raw($v):sanitize_text_field($v));}$out[]=$clean;}return$out;}
	private static function contributions($rows){$out=array();$default=false;$free=false;foreach((array)$rows as$row){if(!is_array($row))continue;$is_free=!$free&&!empty($row['is_free']);$amount=$is_free?0:round((float)($row['amount']??0),2);if(!$is_free&&$amount<=0)continue;$free=$free||$is_free;$is_default=!$default&&!empty($row['is_default']);$default=$default||$is_default;$out[]=array('id'=>sanitize_key($row['id']??'')?:wp_generate_uuid4(),'type'=>$is_free?'free':'paid','amount'=>$amount,'label'=>sanitize_text_field($row['label']??''),'is_default'=>$is_default);}if($out&&!$default)$out[0]['is_default']=true;return$out;}
	private static function save_slots($wid,$slots){$keep=array();foreach($slots as$order=>$row){$start=sanitize_text_field($row['start_time']??$row['start']??'');$end=sanitize_text_field($row['end_time']??$row['end']??'');if(!$start&&!$end)continue;$data=array('workshop_id'=>$wid,'slot_type'=>sanitize_key($row['slot_type']??$row['type']??'live'),'start_time'=>$start,'end_time'=>$end,'meeting_link'=>esc_url_raw($row['meeting_link']??''),'sort_order'=>$order,'status'=>!empty($row['enabled'])||'active'===($row['status']??'')?'active':'inactive');$id=absint($row['id']??0);if($id){GGM_Workshop_Slot::update($id,$data);$keep[]=$id;}elseif($new=GGM_Workshop_Slot::create($data))$keep[]=$new;}GGM_Workshop_Slot::delete_missing($wid,$keep);}
}
